const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:2});
const compact=n=>Math.abs(n)>=1e6?`${fmt(n/1e6)}M`:fmt(n);
const roles={
 captain:{code:'CAPTAIN',name:'国家队长',symbol:'♜',tag:'THE CABINET',mission:'让北港\n如期启动',desc:'80 个技术岗位空缺，首批目标 60 人。内阁选择更快到岗，或一次覆盖更多岗位。',rooms:['内阁宫','国家议程','外交码头'],points:[[48,43],[62,26],[81,56]],cards:[['♟','组合议程','三种方案，一份政治资本'],['⚑','召集表决','每个部门独立作出决定'],['✦','承诺与危机','目标需要实际兑现']],old:'captain-v4',flavour:'筹码有限，选择决定国策'},
 finance:{code:'FINANCE',name:'财政部长',symbol:'◈',tag:'THE TREASURY',mission:'港口开工，\n国库留有余地',desc:'银行与企业已确认 50M LNY。项目还差 40M，工资和债务即将到期。',rooms:['建设工地','债券交易所','国库'],points:[[75,55],[64,24],[48,43]],cards:[['◈','项目拨款','把资金放进建设计划'],['⚖','债券竞价','报价之后，等待真实成交'],['◷','支付日','承诺、付款、开工分开结算']],old:'finance-v3',flavour:'每一枚资金都有去处'},
 central_bank:{code:'CENTRAL_BANK',name:'央行行长',symbol:'◎',tag:'THE RESERVE',mission:'让清算网络\n重新流动',desc:'两家银行出现合计 16M LNY 缺口。抵押品决定救助上限。',rooms:['清算中心','货币政策台','外汇港'],points:[[56,25],[66,24],[81,52]],cards:[['⇄','调配流动性','沿银行网络分配贷款'],['◎','利率走廊','以基点调整资金价格'],['⚓','外汇干预','两种资产同时结算']],old:'central-bank',flavour:'资金流动，银行才会运转'},
 industry:{code:'INDUSTRY',name:'产业部长',symbol:'⚒',tag:'THE FOUNDRY',mission:'从一吨钢材\n到第一批机械',desc:'钢厂与机械厂共享 200 MWh/日。扩产之前，先让生产链接续运转。',rooms:['电站','钢厂与机械厂','扩建工地'],points:[[16,32],[28,22],[44,37]],cards:[['ϟ','电力调度','有限电力，生产链取舍'],['⚒','生产链','矿石、钢材、机械逐日流转'],['⌂','扩建工程','投入之后仍需等待建成']],old:'industry',flavour:'让资源沿生产线转动'},
 trade:{code:'TRADE',name:'贸易部长',symbol:'⚓',tag:'THE HARBOUR',mission:'把钢材送到\n北港工地',desc:'工地需要 120 tonne 钢材，仓内只有 20 tonne。近港快，远港便宜。',rooms:['货源海图','装船码头','海关与航路'],points:[[84,32],[81,53],[68,65]],cards:[['◉','选择货源','距离、成本与库存的取舍'],['⚓','签约发船','货款支出，货物开始航行'],['⌁','航线追踪','在途货物不计入库存']],old:'trade',flavour:'订单只是航程的开始'},
 social:{code:'SOCIAL',name:'社会部长',symbol:'♧',tag:'THE COMMONS',mission:'让一批学员\n走进新工厂',desc:'240 个技术岗位待填补。60 名求职者已具备技能，其余需要培养。',rooms:['技术学院','就业中心','社区诊所'],points:[[37,61],[26,54],[43,62]],cards:[['♧','分配学位','预算与教学容量共同约束'],['♙','岗位匹配','毕业之后，再安排到岗'],['✚','医疗分流','让等候队列逐步缩短']],old:'social',flavour:'每一个阶段都有人留下'}
};
const params=new URLSearchParams(location.search);let role=roles[params.get('role')]?params.get('role'):'finance';
const countryRaw=params.get('country'),countryScope=/^(?:0?[1-9]|[1-6][0-9]|70)$/.test(countryRaw||'')?countryRaw.padStart(2,'0'):null;
const countryOffice=role;
const KEY='econmind-immersive-game-v1'+(countryScope?':country:'+countryScope+':office:'+countryOffice:'');let data;try{data=JSON.parse(localStorage.getItem(KEY))}catch{};if(!data||data.version!==1)data={version:1,roles:{},policies:{}};
const base=()=>({day:128,log:[],receipts:[]});
const initial={
 captain:()=>({...base(),capital:40,plan:'local',support:[0,0,0],approvals:[false,false,false],version:1,active:null,workers:0,graduates:0,commitment:null,crisis:'常态'}),
 finance:()=>({...base(),cash:120e6,allocated:0,committed:false,approvals:[false,false],paid:0,port:0,bond:null,bondOffer:20e6,settled:false}),
 central_bank:()=>({...base(),cash:40e6,fx:80e6,rate:3,rateDraft:3,bank:0,amount:8e6,fxAmount:1e6,banks:[{name:'北港银行',gap:10e6,collateral:16e6,loan:0},{name:'市民银行',gap:6e6,collateral:8e6,loan:0}],loans:[],interest:0}),
 industry:()=>({...base(),cash:100000,ore:2400,steel:100,machines:0,powerSteel:120,target:80,workers:80,capacity:100,expansion:null}),
 trade:()=>({...base(),cash:150000,stock:20,quantity:50,supplier:'near',supply:{near:80,far:200},shipments:[],tariff:5,fx:1000000}),
 social:()=>({...base(),funds:200000,low:300,skilled:60,placed:0,vacancies:240,seats:50,programme:null,placements:[],healthFunds:60000,backlog:120,visits:0,clinic:40,match:30})
};
let s,view=null,catalog=null,activeModule=null,editValues={},editorTab='',catalogFilter='',catalogQuery='';
function setRole(r){role=r;if(!data.roles[r])data.roles[r]=initial[r]();s=data.roles[r];view=null;history.replaceState(null,'',`?role=${r}${countryScope?'&country='+countryScope:''}`);save();render();}
function save(){data.roles[role]=s;localStorage.setItem(KEY,JSON.stringify(data));}
function record(text,terms={}){s.log.unshift({day:s.day,text,terms});s.log=s.log.slice(0,100);save();}
function money(n,c='LNY'){return window.Season1?Season1.Money.from(String(n),c).toCanonicalValue():{amount:String(n),currency:c};}
function qty(n,u){return window.Season1?Season1.quantity(n,u):{amount:String(n),unit:u};}
function day(n){return window.Season1?Season1.simDay(n):{amount:String(n*86400000),unit:'sim_millisecond'};}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function button(text,cmd,extra='',kind='primary'){return `<button class="${kind}" data-cmd="${cmd}" ${extra}>${text}</button>`;}
function stats(items){return `<div class="stats">${items.map(([l,v,u=''])=>`<div class="stat"><small>${l}</small><b>${v} <em>${u}</em></b></div>`).join('')}</div>`;}
function slider(label,key,value,min,max,step,unit){return `<label class="control"><span class="flex"><span>${label}</span><span><input aria-label="${label}精确值" type="number" min="${min}" max="${max}" step="${step}" value="${value}" data-control="${key}"> ${unit}</span></span><input aria-label="${label}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" data-control="${key}"></label>`;}
function sheet(title,body,eyebrow='北港启航 · '+roles[role].name){$('#overlay').innerHTML=`<div class="scrim"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="sheet-header"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2></div><button class="close" data-cmd="close" aria-label="关闭">×</button></header><div class="sheet-body">${body}</div></section></div>`;$('.close').focus({preventScroll:true});}
function showRoom(i){view=Number(i);render();}
function hud(){switch(role){case'captain':return [['政治资本',s.capital,'点'],['已到岗',s.workers,'人'],['议程版本',s.version,'']];case'finance':return[['国库现金',compact(s.cash),'LNY'],['项目已付',compact(s.paid),'LNY'],['受限与缓冲','40M','LNY']];case'central_bank':return[['流动性资金',compact(s.cash),'LNY'],['外汇储备',compact(s.fx),'GCU'],['政策利率',fmt(s.rate),'%']];case'industry':return[['铁矿石',fmt(s.ore),'tonne'],['钢材',fmt(s.steel),'tonne'],['机械',fmt(s.machines),'equipment_unit']];case'trade':return[['企业现金',compact(s.cash),'GCU'],['已到港',s.stock,'tonne'],['在途',s.shipments.filter(x=>!x.arrived).reduce((a,b)=>a+b.quantity,0),'tonne']];case'social':return[['培训预算',compact(s.funds),'LNY'],['待匹配',s.skilled,'人'],['已到岗',s.placed,'人']];}}
function progress(){switch(role){case'captain':return Math.min(100,s.workers/60*100);case'finance':return Math.min(100,s.paid/40e6*100);case'central_bank':return Math.min(100,(16e6-s.banks.reduce((a,b)=>a+Math.max(0,b.gap-b.loan),0))/16e6*100);case'industry':return Math.min(100,s.machines/20*100);case'trade':return Math.min(100,s.stock/120*100);case'social':return Math.min(100,s.placed/100*100);}}
function progressText(){return {captain:`${s.workers||0} / 60 人首批到岗`,finance:`${compact(s.paid||0)} / 40M LNY 项目拨款`,central_bank:`缺口覆盖 ${Math.round(progress())}%`,industry:`${s.machines||0} / 20 equipment_unit`,trade:`${s.stock||0} / 120 tonne 已到港`,social:`${s.placed||0} / 100 人到岗`}[role];}
function nextEvent(){if(role==='captain'&&s.active)return Math.min(...[s.active.graduateDay,s.active.arrivalDay].filter(x=>x>s.day));if(role==='finance'){let ds=[130,136,138,...(s.projectDays||[])];if(s.bond){ds.push(s.bond.maturity);if(!s.settled)ds.push(s.bond.day);}return Math.min(...ds.filter(d=>d>s.day));}if(role==='industry'&&s.expansion&&!s.expansion.done)return s.expansion.end;if(role==='central_bank')return Math.min(...s.loans.filter(x=>!x.repaid).map(x=>x.due));if(role==='trade')return Math.min(...s.shipments.filter(x=>!x.arrived).map(x=>x.arrival));if(role==='social')return Math.min(...[s.programme&&!s.programme.done?s.programme.end:Infinity,...s.placements.filter(x=>!x.done).map(x=>x.due)]);return Infinity;}
function markerText(){switch(role){case'captain':return s.workers?`北港岗位 · ${s.workers} 人已到岗`:s.active?`人才计划 · 第 ${s.active.arrivalDay} 日到岗`:'北港工地 · 80 人缺口';case'finance':return s.paid===40e6?'港口主体开工':s.committed?'建设资金已承诺':`北港项目 · 缺口 ${compact(40e6-s.allocated)} LNY`;case'central_bank':return `清算缺口 · ${compact(s.banks.reduce((a,b)=>a+Math.max(0,b.gap-b.loan),0))} LNY`;case'industry':return `钢厂 · ${production().steel} tonne/日`;case'trade':return `工地库存 · ${s.stock} tonne`;case'social':return s.programme&&!s.programme.done?`培训中 · ${s.programme.n} 人`:`就业中心 · ${s.placed} 人已到岗`;}}
function render(){if(countryScope){$('#game').innerHTML='<main class="game-shell"><div class="edition">正在加载已选定的国家开局资料；World 实时状态尚未连接。</div></main>';return;}const r=roles[role],p=progress(),next=nextEvent();document.title=`${r.name} · 北港启航`;$('#game').innerHTML=`<main class="game-shell"><div class="world" aria-label="共和国互动地图"></div><div class="hud"><button class="identity" data-cmd="roles"><span class="crest">${r.symbol}</span><span><small>ECONMIND · SEASON 1</small><b>${r.name} ⌄</b></span></button><div class="resources">${hud().map(([l,v,u])=>`<div class="resource"><small>${l}</small><b>${v}</b><em>${u}</em></div>`).join('')}</div><div class="time"><span>北港启航</span><strong>第 ${s.day} 日</strong><small>模拟时间 · 自动结算</small></div></div><div class="mission"><div class="eyebrow">第一章 / ${r.tag}</div><h1>${r.mission.replace('\n','<br>')}</h1><p>${r.desc}</p><div class="quest-progress"><i style="width:${p}%"></i></div><small>${progressText()}</small></div><div class="corner-tools"><button class="round" data-cmd="codex" title="行动册 · 全部功能" aria-label="行动册">▤</button><button class="round" data-cmd="history" title="时间线" aria-label="时间线">◷</button><button class="round" data-cmd="help" title="玩法与规则" aria-label="玩法与规则">?</button></div>${r.points.map(([x,y],i)=>`<button class="pin" data-pin="${i}" style="left:${x}%;top:${y}%" data-cmd="room" data-id="${i}" ${role==='finance'&&i===0?'data-drop="fund"':''} aria-label="${r.rooms[i]}"><span class="pin-icon">${r.cards[i][0]}</span><span>${r.rooms[i]}</span></button>`).join('')}<div class="map-status" style="left:51%;top:66%">${markerText()}</div>${mapMotion()}${scenePlay()}${p>=100?`<div class="chapter-complete"><small>CHAPTER OBJECTIVE</small><h2>阶段目标达成</h2><p>${progressText()} · 可继续经营</p></div>`:''}<div class="bottom"><div class="hand">${r.cards.map(([icon,t,d],i)=>`<button class="action-card" data-cmd="room" data-id="${i}"><span class="num">0${i+1}</span><span class="icon">${icon}</span><strong>${t}</strong><small>${d}</small></button>`).join('')}</div><button class="advance" data-cmd="advance"><span>▷</span>推进一日<small>${Number.isFinite(next)?'下一事件 · 第 '+next+' 日':'逐日结算'}</small></button></div><div class="edition">本地体验 · 场景数值为样例 · Season 1 单位结算</div></main>`;if(view!==null)renderRoom();else $('#overlay').innerHTML='';}
function mapMotion(){if(role==='trade')return s.shipments.filter(x=>!x.arrived).map(x=>{const t=Math.min(1,(s.day-x.start)/(x.arrival-x.start));return `<svg class="path-svg" viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M95 82 Q94 60 80 53"/></svg><div class="ship" style="left:${94-14*t}%;top:${80-27*t}%">⛵</div>`}).join('');if(role==='central_bank'&&s.loans.length)return'<svg class="path-svg" viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M56 25 Q59 32 66 24"/></svg>';if(role==='industry')return'<svg class="path-svg" viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M16 32 Q22 35 28 22"/></svg>';if(role==='social'&&s.placements.some(x=>!x.done))return'<svg class="path-svg" viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M37 61 Q27 38 28 22"/></svg>';return'';}
function renderRoom(){({captain:captainRoom,finance:financeRoom,central_bank:centralRoom,industry:industryRoom,trade:tradeRoom,social:socialRoom})[role](view);}
function tail(i){return `<div class="footer-actions">${button('更多'+roles[role].rooms[i]+'行动','codex',`data-id="${i}"`,'secondary')}<span class="hint">行动册包含该职位全部政策入口</span></div>`;}
const plans={local:{title:'本地培养',icon:'♧',cost:8.4e6,days:30,n:80,capital:12,desc:'80 人培养，30 日毕业，再经 7 日安排到岗。'},foreign:{title:'海外引才',icon:'⚓',cost:12e6,days:10,n:60,capital:16,desc:'60 人引入，10 日抵达，再经 7 日安排到岗。'},mixed:{title:'双线培养',icon:'⇄',cost:10.2e6,days:20,n:70,capital:14,desc:'40 人培养、30 人引入，20 日齐备，再经 7 日安排到岗。'}};
function captainRoom(i){const p=plans[s.plan],sum=s.support.reduce((a,b)=>a+b,0);if(i===0)sheet('内阁议程',`<p class="intro">北港技术岗位缺口 80 人。计划生效需要财政、社会与 Captain 对同一版本批准。</p><div class="choice-grid">${Object.entries(plans).map(([k,p])=>`<button class="choice ${s.plan===k?'active':''}" data-cmd="plan" data-id="${k}" ${s.active?'disabled':''}><div class="figure">${p.icon}</div><h3>${p.title}</h3><p>${p.desc}</p><p><b>${compact(p.cost)} LNY · ${p.capital} 政治资本</b></p></button>`).join('')}</div><div class="playboard"><div class="flex spread"><b>议程支持</b><span class="chip">可分配 ${s.capital-sum} 点</span></div><p class="hint">每点支持占用 1 政治资本。三个席位各需 4 点。</p><div class="row">${['财政','社会','Captain'].map((n,j)=>`<div class="col"><p>${n}</p><div class="tally">${button('−','support',`data-id="${j}" data-delta="-1" ${s.active?'disabled':''}`,'mini')}<b>${s.support[j]}</b>${button('+','support',`data-id="${j}" data-delta="1" ${s.active?'disabled':''}`,'mini')}</div></div>`).join('')}</div></div><div class="footer-actions">${button('分配基础支持','support-base',s.active?'disabled':'')}${button('进入内阁表决','room','data-id="1"','secondary')}</div>${tail(i)}`);else if(i===1)sheet('内阁表决',`<p class="intro">${p.title} · 版本 ${s.version}。下列按钮模拟对应席位的独立回应，不代表其他玩家已批准。</p><div class="choice-grid">${['财政部长','社会部长','Captain'].map((n,j)=>`<div class="choice ${s.approvals[j]?'active':''}"><div class="figure">${s.approvals[j]?'✓':'♟'}</div><h3>${n}</h3><p>${s.approvals[j]?'已批准版本 '+s.version:'待独立回应'}</p><p>支持 ${s.support[j]} / 4 点</p><div class="footer-actions">${button('模拟席位批准','approve',`data-id="${j}" ${s.approvals[j]||s.support[j]<4||s.active?'disabled':''}`,'mini')}</div></div>`).join('')}</div>${stats([['资金请求',compact(p.cost),'LNY'],['政治资本占用',Math.max(sum,p.capital),'点'],['预计到岗',s.day+p.days+7,'模拟日']])}<div class="footer-actions">${button(s.active?'计划执行中':'执行已批准计划','enact',s.active||!s.approvals.every(Boolean)?'disabled':'')}${button('调整议程','room','data-id="0"','secondary')}</div>${tail(i)}`);else sheet('承诺与危机',`<p class="intro">目标只在实际到岗后兑现。公开承诺不会直接增加人数或国库资金。</p><div class="playboard"><div class="figure">⚑</div><div class="flex spread"><b>技术人员到岗</b><strong>${s.workers} / 80 人</strong></div><div class="track"><i style="width:${Math.min(s.workers/80*100,100)}%"></i></div><p class="hint">${s.active?'人才齐备：第 '+s.active.graduateDay+' 日；到岗：第 '+s.active.arrivalDay+' 日。':'人才计划尚未生效。'}</p>${s.commitment?`<p class="good">承诺已发布 · 截止第 ${s.commitment} 日 · ${s.workers>=80?'已兑现':s.day>s.commitment?'未兑现':'进行中'}</p>`:button('公布 80 人到岗目标','commitment')}</div><div class="flex spread"><b>危机协调状态</b><span>${s.crisis}</span>${button(s.crisis==='常态'?'启动加强协调':'退出加强协调','crisis','','secondary')}</div>${tail(i)}`);}
// Full capability inventory: all input controls keep their original source anchors.
const roomRules={captain:[/内阁|提案|政治|指令/,/战略|优先|危机|公开/,/峰会/],finance:[/项目|资金|担保|预算/,/债|资产|国企/,/现金|税|规则|例外|压力/],central_bank:[/流动性|融资|准备|银行/,/政策|通胀|公开|前瞻/,/外汇|互换|资本流动|制裁/],industry:[/电|能源|排放|储备/,/生产|采购|维护|设施/,/./],trade:[/订单|供应|投标|招标|数量/,/技术|贷款|融资|投资|联合|开发/,/./],social:[/教育|培训|人才|学位/,/就业|工人|工资|迁移|住房/,/./]};
function roomFor(m){let idx=roomRules[role].findIndex(re=>re.test(m.title));return idx<0?2:idx;}
function openCodex(filter=''){view='codex';catalogFilter=filter;catalogQuery='';renderCodex();}
function renderCodex(){const mods=catalog.modules.filter(m=>m.role===roles[role].code);const filtered=mods.filter(m=>(catalogFilter===''||roomFor(m)===Number(catalogFilter))&&(!catalogQuery||(m.title+' '+m.fields.map(f=>f.label+' '+f.sourceQuote).join(' ')).toLowerCase().includes(catalogQuery.toLowerCase())));sheet('行动册',`<p class="intro">${mods.length} 类行动。选择地点或搜索指标，展开对应参数。复杂政策在规则校验与会签完成前不进入结算。</p><input class="codex-search" placeholder="搜索行动、指标或条款" aria-label="搜索行动" value="${esc(catalogQuery)}" id="catalog-search"><div class="category-row">${['全部',...roles[role].rooms].map((n,i)=>`<button class="${catalogFilter===(i===0?'':i-1)?'active':''}" data-cmd="catalog-filter" data-id="${i===0?'':i-1}">${n}</button>`).join('')}</div><div class="catalog-grid">${filtered.map(m=>`<button class="catalog-card" data-cmd="module" data-id="${m.id}" data-module-card="${m.id}"><span>${roles[role].cards[roomFor(m)][0]}</span><b>${esc(m.title==='VAT'?'增值税':m.title)}</b><small>${m.fields.length} 项可配置 · ${data.policies[m.id]?'已保存 v'+data.policies[m.id].version:'未配置'}</small></button>`).join('')||'<div class="empty">没有匹配的行动</div>'}</div><div class="footer-actions">${button('已保存行动','policies','','secondary')}<a class="hint" href="coverage.html" target="_blank">功能对应表</a></div>`,'完整政策入口 · '+roles[role].name);}
function openModule(id){activeModule=catalog.modules.find(m=>m.id===id&&m.role===roles[role].code);if(!activeModule)return;editValues=structuredClone(data.policies[id]?.values||Object.fromEntries(activeModule.fields.map(f=>[f.key,f.value??(f.type==='number'?0:'')])));editorTab='全部';view='module';renderEditor();}
function fieldUnit(f){let u=editValues[f.key+'__unit']||f.unit||'数量';if(f.currencyFrom&&editValues[f.currencyFrom])u=u.replace(/^[A-Z]{3}/,editValues[f.currencyFrom]);if(f.perCurrencyFrom&&editValues[f.perCurrencyFrom])u=u.replace(/\/[A-Z]{3}$/, '/'+editValues[f.perCurrencyFrom]);if(u.includes('商品单位')){const before=activeModule.fields.slice(0,activeModule.fields.indexOf(f)+1);const commodity=[...before].reverse().find(x=>x.type==='select'&&/商品|资源$/.test(x.label));const name=commodity?editValues[commodity.key]:null;const commodityUnit=catalog.units[name];u=u.replace('商品单位',commodityUnit||'待指定商品单位');}return u;}
function renderField(f){const v=editValues[f.key],id=f.key,unit=fieldUnit(f);let control='';if(f.type==='number'){const min=f.min??(unit==='%'?0:0),max=f.max??Math.max(Number(v)*2,unit==='%'?100:unit.includes('LNY')?1e8:unit.includes('模拟日')?360:1000);control=`<div class="flex"><input type="number" data-field="${id}" aria-label="${esc(f.label)}" value="${esc(v)}" min="${min}" ${f.max!==null&&f.max!==undefined?`max="${f.max}"`:''} step="${f.step||'any'}"><span class="unit">${esc(unit)}</span></div><input type="range" data-field="${id}" aria-label="${esc(f.label)}滑块" min="${min}" max="${max}" step="${f.step||1}" value="${esc(v)}">`;}else if(f.type==='select'){control=`<select data-field="${id}" aria-label="${esc(f.label)}">${(f.options||[]).map(o=>`<option ${o===v?'selected':''}>${esc(o)}</option>`).join('')}</select>`;}else if(f.type==='multi'){control=`<div class="multi">${(f.options||[]).map(o=>`<label><input type="checkbox" data-field="${id}" data-multi="${esc(o)}" ${(v||[]).includes(o)?'checked':''}>${esc(o)}</label>`).join('')}</div>`;}else if(f.type==='text'){control=`<textarea data-field="${id}" aria-label="${esc(f.label)}">${esc(v)}</textarea>`;}else{control=`<div data-structured="${id}">${(Array.isArray(v)?v:[]).map((row,i)=>structuredRow(f,row,i)).join('')}</div>${button('+ 添加一项','add-row',`data-id="${id}"`,'mini')}<span class="hint"> ${f.type==='conditions'?'对象、比较方向、数值和单位':'对象、金额/数量、单位与日期分别保存'}</span>`;}if(unit.includes('待指定')||editValues[id+'__unit'])control+=`<div class="flex"><span class="unit">结算单位</span><select data-unit-field="${id}" aria-label="${esc(f.label)}结算单位"><option value="">待选择</option>${[...new Set(Object.values(catalog.units))].map(u=>`<option ${unit===(f.unit.startsWith('GCU/')?'GCU/':'')+u?'selected':''} value="${f.unit.startsWith('GCU/')?'GCU/':''}${u}">${f.unit.startsWith('GCU/')?'GCU/':''}${u}</option>`).join('')}</select></div>`;return `<div class="field ${['table','conditions','multi'].includes(f.type)?'wide':''}" data-field-wrap="${id}"><label>${esc(f.label)}${f.plan?' · 协作请求':''}</label>${control}<details><summary>规则来源 · ${f.source}</summary><div class="hint" data-no-translate>${esc(f.sourceQuote)}</div></details></div>`;}
function structuredRow(f,row,i){const condition=f.type==='conditions';return `<div class="structured-row" data-row="${i}"><input aria-label="${esc(f.label)}对象${i+1}" placeholder="${condition?'指标 / 条件对象':'部门 / 资产 / 商品'}" value="${esc(row.subject||'')}" data-row-key="subject" data-id="${f.key}" data-index="${i}">${condition?`<select aria-label="比较方向" data-row-key="operator" data-id="${f.key}" data-index="${i}">${['≥','≤','=','>','<'].map(o=>`<option ${row.operator===o?'selected':''}>${o}</option>`).join('')}</select>`:`<input type="number" aria-label="生效模拟日" value="${row.day??s.day}" min="0" step="1" data-row-key="day" data-id="${f.key}" data-index="${i}">`}<input type="number" aria-label="金额或数量" value="${row.amount??0}" step="any" data-row-key="amount" data-id="${f.key}" data-index="${i}"><input aria-label="单位" placeholder="LNY / 人 / %" value="${esc(row.unit||'LNY')}" data-row-key="unit" data-id="${f.key}" data-index="${i}">${button('×','remove-row',`data-id="${f.key}" data-index="${i}"`,'mini')}</div>`;}
function renderEditor(){const m=activeModule,tabs=['全部',...new Set(m.fields.map(f=>f.tab||'参数')),'结果'];const saved=data.policies[m.id];sheet(esc(m.title),`<div class="ribbon">${roles[role].rooms[roomFor(m)]} · ${saved?'版本 '+saved.version+' · '+saved.status:'尚未保存'} · 联合事项按规格会签</div><div class="editor-tabs">${tabs.map(t=>`<button data-cmd="editor-tab" data-id="${t}" class="${editorTab===t?'active':''}">${t}</button>`).join('')}</div>${editorTab==='结果'?`<div>${m.readouts.map(o=>`<div class="readout" data-readout="${o.source}"><span>${esc(o.label)}</span><span>待结算</span></div>`).join('')||'<p class="hint">该行动没有独立结果字段。</p>'}</div>`:`<div class="edit-fields">${m.fields.filter(f=>editorTab==='全部'||(f.tab||'参数')===editorTab).map(renderField).join('')}</div>`}<div class="footer-actions">${button('保存行动','save-policy')}${button('返回行动册','codex','','secondary')}${button('查看原文','source-module','','mini')}</div><p class="hint">保存保留完整参数与版本。该行动尚未进入正式引擎结算；批准记录不会随新版本自动沿用。</p>`,'完整功能 · '+m.id);}
function typedField(f,value){if(f.type!=='number')return {type:f.type,value};if(value===null||value==='')throw Error(f.label+'需要填写数值');const n=Number(value);if(!Number.isFinite(n))throw Error(f.label+'必须是有效数值');if(f.min!==undefined&&f.min!==null&&n<f.min)throw Error(f.label+'低于最小值');if(f.max!==undefined&&f.max!==null&&n>f.max)throw Error(f.label+'超出最大值');const u=fieldUnit(f)==='数量'?'quantity':fieldUnit(f);if(u==='人'&&!Number.isInteger(n))throw Error(f.label+'必须是整人数');if(/^[A-Z]{3}$/.test(u))return{type:'Money',value:money(n,u)};if(u==='%')return n>=0&&n<=100?{type:'Rate',value:Season1.ratio(n)}:{type:'Quantity',value:qty(n,'percent')};if(u==='第N模拟日'||u==='模拟日'){if(!Number.isInteger(n))throw Error(f.label+'必须为整模拟日');return{type:'SimTime',value:day(n),displayUnit:u};}const price=u.match(/^([A-Z]{3})\/(.+)$/);const dict={'人':'person','政治资本':'political_capital','商品单位':'commodity_unit','能力单位':'capacity_unit','套':'housing_unit','公顷':'hectare','床':'bed','次/模拟日':'visit/sim_day','倍':'multiple','户':'household','小时':'hour','模拟日':'sim_day','每单位面值':'price_per_face','商品单位/模拟日':'commodity_unit/sim_day','MWh/模拟日':'MWh/sim_day','shipments/模拟日':'shipments/sim_day','tCO2e/单位产出':'tCO2e/output_unit'};const raw=price?price[2]:u;const normalized=dict[raw]||raw;if(!/^[A-Za-z][A-Za-z0-9 _/-]{0,63}$/.test(normalized))return{type:'UnitPending',amount:String(n),displayUnit:u,status:'需确定商品单位'};return price?{type:'Price',value:Season1.Price.from(String(n),price[1],normalized).toCanonicalValue()}:{type:'Quantity',value:qty(n,normalized)};}
function savePolicy(){try{const terms={};activeModule.fields.forEach(f=>{terms[f.key]=typedField(f,editValues[f.key]);if(['conditions','table'].includes(f.type)){const rows=editValues[f.key];if(!Array.isArray(rows))throw Error(f.label+'需要结构化条目');for(const row of rows){if(!row.subject?.trim()||!row.unit?.trim()||!Number.isFinite(Number(row.amount)))throw Error(f.label+'条目需要对象、数值和单位');}terms[f.key].value=rows.map(row=>({...row,amount:String(row.amount),typed:typedField({type:'number',key:f.key+'-row',label:f.label,unit:row.unit},row.amount),time:row.day===undefined?undefined:day(row.day)}));}});const previous=data.policies[activeModule.id];data.policies[activeModule.id]={id:activeModule.id,role,version:(previous?.version||0)+1,values:structuredClone(editValues),terms,status:'待规则校验',approvals:[],savedDay:s.day};record('保存行动：'+activeModule.title+' · 待规则校验');renderEditor();toast('完整参数已保存；新版本需重新校验与会签');}catch(e){toast(e.message);}}
function policies(){view='policies';let ps=Object.values(data.policies).filter(p=>p.role===role);sheet('已保存行动',`<div class="log-list">${ps.map(p=>`<div class="log-item"><small>第 ${p.savedDay} 日 · 版本 ${p.version} · ${p.status}</small><b>${catalog.modules.find(m=>m.id===p.id)?.title||p.id}</b> ${button('查看参数','module',`data-id="${p.id}"`,'mini')}</div>`).join('')||'<div class="empty">尚无保存的行动</div>'}</div><div class="footer-actions">${button('导出完整记录','export','','secondary')}${button('返回行动册','codex','','secondary')}</div>`);}
async function showSource(){const codes=[...new Set(activeModule.sources.map(a=>a.split('-U')[0]))];const texts=Object.fromEntries(await Promise.all(codes.map(async code=>[code,await fetch(`../specs-markdown-2026-09-27/${code}.md`).then(r=>r.text())])));const blocks=activeModule.sources.map(anchor=>{const source=texts[anchor.split('-U')[0]],start=source.indexOf('### '+anchor+'\n'),end=source.indexOf('\n### ',start+5);return start>=0?source.slice(start,end<0?source.length:end):anchor;});sheet('规格原文',`<div class="source-quote">${esc(blocks.join('\n\n'))}</div><div class="footer-actions">${button('返回行动','back-editor','','secondary')}</div>`);}

function financeRoom(i){if(i===0){const n=s.allocated/5e6;sheet('北港建设资金',`<p class="intro">项目总额 90M LNY，银行 20M、私人 30M 已确认。每枚国库筹码代表 5M LNY，可拖动或点击分配。</p><div class="playboard"><div class="row"><div class="col dropzone" data-drop="return"><h3>国库可分配 · ${compact(40e6-s.allocated)} LNY</h3><div class="tokens">${Array.from({length:8-n},(_,j)=>`<button class="token" draggable="${!s.committed}" data-token="fund" data-cmd="fund" data-delta="1" aria-label="分配 5M LNY" ${s.committed?'disabled':''}>5M</button>`).join('')}</div><p class="hint">20M 专项资金、20M 安全缓冲及既有支付已预留。</p></div><div class="col dropzone" data-drop="fund"><h3>⚓ 北港项目 · ${compact(s.allocated)} LNY</h3><div class="tokens">${Array.from({length:n},()=>`<button class="token" draggable="${!s.committed}" data-token="return" data-cmd="fund" data-delta="-1" aria-label="收回 5M LNY" ${s.committed?'disabled':''}>5M</button>`).join('')}</div><p class="hint">${s.committed?'已承诺资金不可随意撤回':'点击项目筹码可收回'}</p></div></div><div class="track"><i style="width:${20/90*100}%"></i><i style="width:${30/90*100}%"></i><i style="width:${s.allocated/90e6*100}%"></i></div><div class="flex spread"><small>银行 20M · 私人 30M · 国库 ${compact(s.allocated)}</small><b>缺口 ${compact(40e6-s.allocated)} LNY</b></div></div><div class="flex spread"><span class="hint">项目所有者：产业部长 · 固定范围 · 版本 ${s.allocated/5e6+1}</span><span class="stamp">${s.approvals.map((x,j)=>['产业','Captain'][j]+(x?' ✓':' 待确认')).join(' / ')}</span></div><div class="footer-actions">${s.approvals.map((x,j)=>button('模拟'+['产业','Captain'][j]+'确认','finance-approve',`data-id="${j}" ${x||s.allocated!==40e6?'disabled':''}`,'secondary')).join('')}${button(s.committed?'已承诺':'承诺项目资金','fund-commit',s.committed||s.allocated!==40e6||!s.approvals.every(Boolean)?'disabled':'')}</div>${tail(i)}`);}else if(i===1){const allocated=Math.min(s.bondOffer,20e6),net=allocated*.98-200000;sheet('债券竞价',`<p class="intro">样例买盘：国内银行 12M、其他投资者 8M LNY。统一价格为面值的 98%，发行费 200,000 LNY。</p><div class="playboard blue"><div class="choice-grid"><div class="choice"><div class="figure">▥</div><h3>国内银行</h3><p>12M LNY 申购</p></div><div class="choice"><div class="figure">♙</div><h3>其他投资者</h3><p>8M LNY 申购</p></div><div class="choice"><div class="figure">⚖</div><h3>成交上限</h3><p>20M LNY 面值</p></div></div>${slider('拟发行面值','bondOffer',s.bondOffer,1e6,40e6,1e6,'LNY')}${stats([['预计分配',compact(allocated),'LNY'],['交割净收入',compact(net),'LNY'],['未被认购',compact(s.bondOffer-allocated),'LNY']])}</div><p class="hint">票息 3%/年，360 日到期。交割日为发行次日；到期需支付本金与票息。固定买盘为本场景样例。</p><div class="footer-actions">${button(s.bond?(s.settled?'已交割':'等待交割'):'发行并配售','issue',s.bond?'disabled':'')}</div>${tail(i)}`);}else{const list=[{day:130,label:'工资支出',amount:-12e6},{day:130,label:'税款到账',amount:5e6},{day:136,label:'既有债务本金及利息',amount:-22e6},{day:138,label:'既有采购',amount:-6e6}];if(s.committed)list.push({day:s.projectDays[0],label:'项目首期',amount:-20e6},{day:s.projectDays[1],label:'项目第二期',amount:-20e6});if(s.bond)list.push({day:s.bond.day,label:'债券交割',amount:s.bond.net},{day:s.bond.maturity,label:'债券到期本息',amount:-s.bond.allocated*1.03});list.sort((a,b)=>a.day-b.day);sheet('支付日',`<p class="intro">现金只在收付日改变。已经承诺的建设资金在国库内冻结，不能重复分配。</p><div class="playboard"><div class="figure">${s.paid===40e6?'🏗':'◈'}</div>${stats([['当前国库',compact(s.cash),'LNY'],['建设已支付',compact(s.paid),'LNY'],['建设阶段',s.paid===40e6?'主体开工':s.paid?'场地施工':s.committed?'等待首款':'未承诺','']])}</div><div class="log-list">${list.map(x=>`<div class="log-item"><small>第 ${x.day} 日 · ${x.day<=s.day?'已结算':'待到期'}</small>${x.label}<b style="float:right">${x.amount>=0?'+':''}${compact(x.amount)} LNY</b></div>`).join('')}</div><div class="footer-actions">${button('推进至下一事件','next-event',!Number.isFinite(nextEvent())?'disabled':'')}${button('推进一日','advance','','secondary')}</div>${tail(i)}`);}}
function centralRoom(i){const bank=s.banks[s.bank],limit=bank.collateral*.8-bank.loan;if(i===0)sheet('清算网络',`<p class="intro">贷款按抵押品价值的 80% 封顶。央行放款形成债权，7 模拟日后按 ${(s.rate+.5).toFixed(2)}% 年利率归还；本场景银行按期偿还。</p><div class="playboard blue"><div class="bank-net"><div class="bank-center"><strong>◎</strong><span>央行</span><small>${compact(s.cash)} LNY</small></div><div class="banks">${s.banks.map((b,j)=>`<button class="bank ${s.bank===j?'active':''} ${b.loan>=b.gap?'covered':''}" data-cmd="bank" data-id="${j}"><b>${b.name} ${b.loan>=b.gap?'✓':''}</b><small>当前缺口 ${compact(Math.max(0,b.gap-b.loan))} LNY · 抵押额度 ${compact(b.collateral*.8)} LNY</small><div class="track"><i style="width:${Math.min(100,b.loan/b.gap*100)}%"></i></div></button>`).join('')}</div></div>${slider('本次贷款','amount',s.amount,0,Math.min(limit,s.cash),200000,'LNY')}<div class="flex spread"><span class="hint">${bank.name} · 剩余可贷 ${compact(limit)} LNY</span><b>放款后缺口 ${compact(Math.max(0,bank.gap-bank.loan-s.amount))} LNY</b></div></div><div class="footer-actions">${button('发放抵押贷款','lend',s.amount<=0||s.amount>limit||s.amount>s.cash?'disabled':'')}${button('查看贷款期限','history','','secondary')}</div>${tail(i)}`);else if(i===1)sheet('政策利率',`<p class="intro">每档 25 bp。当前利率只影响新作出的政策报价，既有固定利率贷款保持合同利率。</p><div class="playboard blue"><div class="figure">◎</div><div style="text-align:center"><div class="big-value">${(s.rateDraft??s.rate).toFixed(2)} <small>% 拟公布年利率</small></div></div>${slider('政策利率','rateDraft',s.rateDraft??s.rate,0,10,.25,'%')}<div class="flex spread"><span>−25 bp</span><span>1 bp = 0.01 个百分点</span><span>+25 bp</span></div></div><p class="hint">物价、汇率与产出的变化需要正式模型结算，本页不生成无依据的预测。</p><div class="footer-actions">${button('公布本次利率','announce-rate')}</div>${tail(i)}`);else sheet('外汇干预',`<p class="intro">样例即期价格 7 LNY / GCU。卖出 GCU 时减少外汇储备，并回收对应 LNY。</p><div class="playboard blue"><div class="flow-chain"><div class="factory"><div class="figure">◎</div><b>外汇储备</b><small>${compact(s.fx)} GCU</small></div><div class="flow-arrow">⇄</div><div class="factory"><div class="figure">◈</div><b>本币资产</b><small>${compact(s.cash)} LNY</small></div></div>${slider('卖出外汇','fxAmount',s.fxAmount,0,Math.min(s.fx,10e6),1e5,'GCU')}${stats([['卖出',compact(s.fxAmount),'GCU'],['回收',compact(s.fxAmount*7),'LNY'],['成交价',7,'LNY/GCU']])}</div><div class="footer-actions">${button('按报价成交','fx',s.fxAmount<=0||s.fxAmount>s.fx?'disabled':'')}</div>${tail(i)}`);}
function production(){let steel=Math.max(0,Math.floor(Math.min(s.target,s.workers,s.capacity,s.powerSteel/2,s.ore/2,s.cash/20)));let machines=Math.max(0,Math.floor(Math.min(10,(200-s.powerSteel)/10,(s.steel+steel)/5,(s.cash-steel*20)/100)));return {steel,machines};}
function industryRoom(i){let p=production();if(i===0)sheet('电力调度',`<p class="intro">民生基础用电另有 60 MWh/日保障。以下 200 MWh/日由钢厂与机械厂共同使用；供电不作为库存累积。</p><div class="playboard"><div class="flow-chain"><div class="factory"><div class="figure">ϟ</div><b>电站</b><small>200 MWh/日</small></div><div class="flow-arrow">→</div><div class="factory"><div class="figure">⚒</div><b>钢厂</b><small>${s.powerSteel} MWh/日</small></div><div class="flow-arrow">→</div><div class="factory"><div class="figure">⚙</div><b>机械厂</b><small>${200-s.powerSteel} MWh/日</small></div></div>${slider('钢厂供电','powerSteel',s.powerSteel,0,200,10,'MWh/日')}${stats([['钢材日产',p.steel,'tonne/日'],['机械日产',p.machines,'equipment_unit/日'],['每日现金支出',p.steel*20+p.machines*100,'LNY/日']])}</div><div class="footer-actions">${button('按当前配置生产一日','advance')}</div>${tail(i)}`);else if(i===1)sheet('矿石 → 钢材 → 机械',`<p class="intro">每 tonne 钢材消耗 2 tonne 矿石、2 MWh 电力及 20 LNY；每台机械消耗 5 tonne 钢材、10 MWh 及 100 LNY。系数为本场景样例。</p><div class="playboard"><div class="flow-chain">${[['⛰','矿石',s.ore,'tonne'],['⚒','钢材',s.steel,'tonne'],['⚙','机械',s.machines,'equipment_unit']].map(([icon,t,n,u],j)=>`${j?'<span class="flow-arrow">→</span>':''}<div class="factory"><div class="figure">${icon}</div><b>${t}</b><small>${fmt(n)} ${u}</small></div>`).join('')}</div>${slider('钢材目标','target',s.target,0,s.capacity,5,'tonne/日')}<p class="hint">可用技术工人 ${s.workers} 人，基础产能 ${s.capacity} tonne/日。实际产量取资源与产能约束的最小值。</p>${stats([['下日钢材净变化',p.steel-p.machines*5,'tonne'],['下日机械增加',p.machines,'equipment_unit'],['产业现金',fmt(s.cash),'LNY']])}</div><div class="footer-actions">${button('生产一日','advance')}${button('调整供电','room','data-id="0"','secondary')}</div>${tail(i)}`);else sheet('钢厂扩建',`<p class="intro">建设需要 20,000 LNY 和 5 模拟日。投产后产能增加 40 tonne/日，但仍需要工人和供电。</p><div class="playboard"><div class="figure">🏗</div>${stats([['建设支出','20,000','LNY'],['建设时间',5,'模拟日'],['新增产能',40,'tonne/日']])}<p class="hint">${s.expansion?(s.expansion.done?'扩建已投产；技术工人与电力约束仍然有效。':'施工中 · 第 '+s.expansion.end+' 日完工'):'产业建设预算已批准，开工后扣减现金。'}</p></div><div class="footer-actions">${button(s.expansion?'工程已开工':'支付并开工','expand',s.expansion||s.cash<20000?'disabled':'')}</div>${tail(i)}`);}
const suppliers={near:{name:'阿斯特近港',price:720,freight:30,days:3},far:{name:'索拉远港',price:620,freight:80,days:7}};
function quote(){const p=suppliers[s.supplier];return {goods:s.quantity*p.price,freight:s.quantity*p.freight,insurance:s.quantity*5,tax:s.quantity*p.price*s.tariff/100,total:s.quantity*(p.price+p.freight+5+p.price*s.tariff/100)};}
function tradeRoom(i){const p=suppliers[s.supplier],q=quote();if(i===0)sheet('货源海图',`<p class="intro">钢材供应商的库存为有限存量。近港贵但快，远港便宜但多等待 4 日。</p><div class="choice-grid" style="grid-template-columns:1fr 1fr">${Object.entries(suppliers).map(([k,x])=>`<button class="choice ${s.supplier===k?'active':''}" data-cmd="supplier" data-id="${k}"><div class="figure">${k==='near'?'⚓':'⛵'}</div><h3>${x.name}</h3><p>${x.price} GCU/tonne · 运费 ${x.freight} GCU/tonne</p><p>${x.days} 模拟日航程 · 剩余 ${s.supply[k]} tonne</p></button>`).join('')}</div><div class="route-map"><div class="island left">⚓<small>${p.name}</small></div><div class="route-ship">⛵</div><div class="island right">⌂<small>北港</small></div></div>${slider('采购钢材','quantity',s.quantity,0,s.supply[s.supplier],5,'tonne')}${stats([['含税总成本',fmt(q.total),'GCU'],['预计到港',s.day+p.days,'模拟日'],['到港后库存',s.stock+s.quantity,'tonne']])}<div class="footer-actions">${button('前往签约装船','room','data-id="1"')}</div>${tail(i)}`);else if(i===1)sheet('签约装船',`<p class="intro">${p.name} → 北港。企业自有 GCU 支付；官方外汇储备不参与本笔交易。</p><div class="playboard blue"><div class="figure">⛵</div>${stats([['采购数量',s.quantity,'tonne'],['航程',p.days,'模拟日'],['企业现金',fmt(s.cash),'GCU']])}<div class="log-list">${[['货款',q.goods],['运费',q.freight],['保险',q.insurance],['关税',q.tax]].map(([n,v])=>`<div class="flex spread"><small>${n}</small><b>${fmt(v)} GCU</b></div>`).join('')}</div><div class="track"><i style="width:${Math.min(100,q.total/Math.max(s.cash,1)*100)}%"></i></div><div class="flex spread"><strong>合计 ${fmt(q.total)} GCU</strong><span class="hint">付款后 ${fmt(s.cash-q.total)} GCU</span></div></div>${q.total>s.cash?'<p class="warning">企业现金不足，需要减少采购量。</p>':''}<div class="footer-actions">${button('签约、付款并装船','ship',s.quantity<=0||s.quantity>s.supply[s.supplier]||q.total>s.cash?'disabled':'')}${button('调整货源和数量','room','data-id="0"','secondary')}</div>${tail(i)}`);else sheet('海关与航路',`<p class="intro">在途货物独立记录，只有到港才计入工地可用库存。</p><div class="log-list">${s.shipments.map(x=>`<div class="log-item"><small>${x.name} → 北港 · ${x.quantity} tonne · 第 ${x.arrival} 日到港</small><div class="route-map"><div class="island left">⚓</div><div class="route-ship" style="left:${10+Math.min(1,(s.day-x.start)/(x.arrival-x.start))*70}%">⛵</div><div class="island right">⌂</div></div><b>${x.arrived?'已完成交付':'还有 '+(x.arrival-s.day)+' 模拟日'}</b></div>`).join('')||'<div class="empty">港口尚无在途订单</div>'}</div>${slider('新订单进口关税','tariff',s.tariff,0,30,1,'%')}<p class="hint">调整关税只影响新订单，已签约订单按锁定条款结算。</p><div class="footer-actions">${button('推进至下一到港日','next-event',!Number.isFinite(nextEvent())?'disabled':'')}${button('推进一日','advance','','secondary')}</div>${tail(i)}`);}
function people(n,cls=''){return `<div class="people" aria-label="${n} 人">${Array.from({length:Math.min(40,Math.ceil(n/5))},()=>`<span class="person ${cls}"></span>`).join('')}</div><div class="people-label">每个图标约代表 5 人 · 合计 ${n} 人</div>`;}
function socialRoom(i){if(i===0)sheet('技术学院',`<p class="intro">申请者 120 人、教师容量 80 人、设施容量 100 人。每人培训成本 2,000 LNY，培养期 30 模拟日，样例毕业率 90%。</p><div class="playboard"><div class="row"><div class="col"><div class="figure">♧</div><b>本期学员</b>${people(s.programme?s.programme.n:s.seats,'learning')}</div><div class="col"><div class="figure">⚒</div><b>工厂空缺</b>${people(s.vacancies)}</div></div>${slider('招生名额','seats',s.seats,0,80,5,'人')}${stats([['培训成本',fmt(s.seats*2000),'LNY'],['预计毕业',Math.floor(s.seats*.9),'人'],['预计毕业日',s.day+30,'模拟日']])}</div>${s.programme?`<p class="good">${s.programme.done?'本期已毕业 '+s.programme.graduates+' 人，待就业安排':'培训进行中 · 第 '+s.programme.end+' 日毕业'}</p>`:''}<div class="footer-actions">${button(s.programme&&!s.programme.done?'培训进行中':'缴费并开班','train',s.seats<=0||s.seats*2000>s.funds||(s.programme&&!s.programme.done)?'disabled':'')}${button('推进到下一事件','next-event',!Number.isFinite(nextEvent())?'disabled':'','secondary')}</div>${tail(i)}`);else if(i===1)sheet('就业中心',`<p class="intro">具备技能不代表已经到岗。匹配后安排 7 模拟日入职，到岗前计入途中人员。</p><div class="playboard"><div class="row"><div class="col"><b>具备技能</b>${people(s.skilled)}</div><div class="col"><b>入职途中</b>${people(s.placements.filter(x=>!x.done).reduce((a,b)=>a+b.n,0),'travel')}</div><div class="col"><b>已经到岗</b>${people(s.placed)}</div></div>${slider('安排入职','match',s.match,0,Math.min(s.skilled,s.vacancies-s.placements.filter(x=>!x.done).reduce((a,b)=>a+b.n,0)),5,'人')}</div><div class="footer-actions">${button('确认岗位匹配','match',s.match<=0||s.match>s.skilled?'disabled':'')}${button('推进到下一事件','next-event',!Number.isFinite(nextEvent())?'disabled':'','secondary')}</div>${tail(i)}`);else sheet('社区诊所',`<p class="intro">一次分流最多接诊 60 人，单人费用 100 LNY。资金从已批准的医疗预算扣减，与培训预算分开。</p><div class="playboard"><div class="row"><div class="col"><b>等候就诊</b>${people(s.backlog,'learning')}</div><div class="col"><b>累计完成</b>${people(s.visits)}</div></div>${slider('本次接诊','clinic',s.clinic,0,Math.min(60,s.backlog),5,'人')}${stats([['本次费用',s.clinic*100,'LNY'],['医疗预算',fmt(s.healthFunds),'LNY'],['剩余等候',s.backlog-s.clinic,'人']])}</div><div class="footer-actions">${button('接诊并结算','clinic',s.clinic<=0||s.clinic>s.backlog||s.clinic*100>s.healthFunds?'disabled':'')}</div>${tail(i)}`);}
function stepOne(){s.day++;let messages=[];switch(role){case'captain':if(s.active){if(s.day===s.active.graduateDay){s.graduates=s.active.n;messages.push('人才已齐备 '+s.active.n+' 人，开始安排到岗');}if(s.day===s.active.arrivalDay){s.workers+=s.active.n;s.graduates=0;messages.push(s.active.n+' 人到达北港岗位');}}break;case'finance':{if(s.day===130){s.cash-=7e6;messages.push('工资 −12M LNY，税款 +5M LNY');}if(s.day===136){s.cash-=22e6;messages.push('既有债务本息 −22M LNY');}if(s.day===138){s.cash-=6e6;messages.push('既有采购 −6M LNY');}if(s.committed&&s.projectDays.includes(s.day)){s.cash-=20e6;s.paid+=20e6;s.port=s.paid/20e6;messages.push('建设付款 −20M LNY；'+(s.paid===40e6?'主体开工':'场地施工'));}if(s.bond&&!s.settled&&s.day===s.bond.day){s.cash+=s.bond.net;s.settled=true;messages.push('债券交割 +'+compact(s.bond.net)+' LNY');}if(s.bond&&s.day===s.bond.maturity){s.cash-=s.bond.allocated*1.03;messages.push('债券到期本息 −'+compact(s.bond.allocated*1.03)+' LNY');}break;}case'central_bank':for(const x of s.loans){if(!x.repaid&&s.day>=x.due){const interest=Season1.interestMinor(Math.round(x.principal*100),Math.round((x.rate??3.5)*100),7)/100;s.cash+=x.principal+interest;s.interest+=interest;x.repaid=true;s.banks[x.bank].loan-=x.principal;s.banks[x.bank].gap=Math.max(0,s.banks[x.bank].gap-x.principal);messages.push('贷款归还 '+fmt(x.principal)+' LNY；利息 '+fmt(interest)+' LNY');}}break;case'industry':{let p=s.batch?.remaining>0?production():{steel:0,machines:0};s.ore-=p.steel*2;s.steel+=p.steel-p.machines*5;s.machines+=p.machines;s.cash-=p.steel*20+p.machines*100;if(s.batch?.remaining>0){s.batch.remaining--;messages.push(`生产 ${p.steel} tonne 钢材、${p.machines} equipment_unit 机械`);if(!s.batch.remaining)messages.push(`批次完成 · 矿石消耗 ${s.batch.ore-s.ore} tonne，机械增加 ${s.machines-s.batch.machines} equipment_unit，现金支出 ${s.batch.cash-s.cash} LNY`);}if(s.expansion&&!s.expansion.done&&s.day>=s.expansion.end){s.capacity+=40;s.expansion.done=true;messages.push('钢厂扩建完工，新增 40 tonne/日产能');}break;}case'trade':for(const x of s.shipments){if(!x.arrived&&s.day>=x.arrival){s.stock+=x.quantity;x.arrived=true;messages.push(x.quantity+' tonne 钢材到港');}}break;case'social':if(s.programme&&!s.programme.done&&s.day>=s.programme.end){s.programme.done=true;s.programme.graduates=Math.floor(s.programme.n*.9);s.skilled+=s.programme.graduates;s.low+=s.programme.n-s.programme.graduates;messages.push(s.programme.graduates+' 人毕业，进入就业匹配');}for(const p of s.placements){if(!p.done&&s.day>=p.due){p.done=true;s.placed+=p.n;s.vacancies-=p.n;messages.push(p.n+' 人正式到岗');}}break;}
 if(messages.length)record(messages.join('；'),{time:day(s.day),resources:hud()});save();return messages;}
function advance(n=1){n=Math.max(1,Math.min(366,n));let messages=[];for(let i=0;i<n;i++)messages.push(...stepOne());render();toast(messages.length?messages.slice(-2).join('；'):'第 '+s.day+' 日 · 暂无到期事件');}
function genericHistory(){view='history';sheet('时间线',`<div class="log-list">${s.log.map(x=>`<div class="log-item"><small>第 ${x.day} 模拟日</small>${esc(x.text)}</div>`).join('')||'<div class="empty">第一项行动尚未发生</div>'}</div><div class="footer-actions">${button('导出记录','export','','secondary')}</div>`);}
function rolePicker(){view='roles';sheet('选择席位',`<p class="intro">六个席位分别保留本地进度。各角色是独立体验场景，尚未共享国家状态。</p><div class="role-grid">${Object.entries(roles).map(([k,r])=>`<button class="role-pick" data-cmd="switch" data-id="${k}"><div class="figure">${r.symbol}</div><b>${r.name}</b><p>${r.flavour}</p></button>`).join('')}</div>`,'ECONMIND · SEASON 1');}
function help(){view='help';sheet('玩法与规则',`<p class="intro">点击地图上的地点，或使用下方三张行动牌。每次选择都改变有限资源、合同阶段或交付时间。时间自动推进。顶部可以暂停或调整速度；离开页面不补算离线天数。</p><div class="log-list"><div class="log-item">1 · 观察缺口。左上角给出当前阶段目标。</div><div class="log-item">2 · 选择方案。数字控件提供单位；资金筹码支持拖动与点击。</div><div class="log-item">3 · 查看后果。签约、支付、运输、毕业与到岗按阶段分开。</div><div class="log-item">4 · 点击场景物件。各地点文件、图纸和合约涵盖该职位功能；待核验文书保留版本。</div></div><p class="hint">本地样例，非正式赛季。数值类型使用 Season 1 Money / Quantity / Price / Rate / SimTime。主循环系数与场景均在规则说明中标为样例；不预测未建模的宏观结果。</p><div class="footer-actions"><a class="secondary" href="../${roles[role].old}/" target="_blank">保留的上一版</a><a class="secondary" href="coverage.html" target="_blank">接口覆盖</a>${button('重置本角色体验','reset-check','','mini')}</div>`);}
function clampControl(key,v){const el=document.querySelector(`[data-control="${key}"]`);const min=Number(el.min),max=Number(el.max);if(['seats','match','clinic'].includes(key))v=Math.floor(v);return Math.min(max,Math.max(min,Number.isFinite(v)?v:min));}
function exportState(){const blob=new Blob([JSON.stringify({role,scenario:s,policies:Object.values(data.policies).filter(p=>p.role===role),unitSource:Season1.sourceSHA},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`econmind-${role}-day-${s.day}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
const commands={
 close:()=>{view=null;$('#overlay').innerHTML='';},room:b=>showRoom(b.dataset.id),roles:rolePicker,switch:b=>setRole(b.dataset.id),help,history:genericHistory,advance:()=>advance(),
 'next-event':()=>{const next=nextEvent();if(Number.isFinite(next)&&next>s.day)advance(next-s.day);else toast('没有待处理的未来事件');},
 codex:b=>openCodex(b?.dataset.id===undefined?'':Number(b.dataset.id)),
 'catalog-filter':b=>{catalogFilter=b.dataset.id===''?'':Number(b.dataset.id);renderCodex();},module:b=>openModule(b.dataset.id),
 'editor-tab':b=>{editorTab=b.dataset.id;renderEditor();},'save-policy':savePolicy,'source-module':showSource,'back-editor':renderEditor,policies,export:exportState,
 'add-row':b=>{const key=b.dataset.id;editValues[key]??=[];editValues[key].push({subject:'',operator:'≥',amount:0,unit:'LNY',day:s.day});renderEditor();},
 'remove-row':b=>{editValues[b.dataset.id].splice(Number(b.dataset.index),1);renderEditor();},
 'reset-check':()=>sheet('重新开始本角色',`<p class="intro">将清除当前角色的场景进度。其他角色和已保存文书保留。</p><div class="footer-actions">${button('重新开始','reset','','primary danger')}${button('保留进度','close','','secondary')}</div>`),
 reset:()=>{s=initial[role]();save();view=null;render();toast('本角色已重新开始');},
 plan:b=>{if(s.active)return;s.plan=b.dataset.id;s.version++;s.approvals=[false,false,false];save();view===null?render():renderRoom();},
 support:b=>{if(s.active)return;const i=Number(b.dataset.id),d=Number(b.dataset.delta);if(s.support[i]+d<0||s.support.reduce((a,b)=>a+b,0)+d>s.capital)return;s.support[i]+=d;s.version++;s.approvals=[false,false,false];save();view===null?render():renderRoom();},
 'support-base':()=>{if(s.active||s.capital<12)return;s.support=[4,4,4];s.version++;s.approvals=[false,false,false];save();renderRoom();},
 approve:b=>{const i=Number(b.dataset.id);if(s.support[i]<4||s.active)return;s.approvals[i]=true;record(['财政','社会','Captain'][i]+'模拟席位批准议程 v'+s.version);renderRoom();},
 enact:()=>{const p=plans[s.plan],cost=Math.max(p.capital,s.support.reduce((a,b)=>a+b,0));if(s.active||!s.approvals.every(Boolean)||cost>s.capital)return;s.capital-=cost;s.active={...p,graduateDay:s.day+p.days,arrivalDay:s.day+p.days+7,version:s.version};record('人才计划生效：'+p.title,{funding:money(p.cost),capital:qty(cost,'political_capital'),people:qty(p.n,'person'),arrival:day(s.active.arrivalDay)});view=null;render();toast('计划生效 · 人才将按期培养、抵达与到岗');},
 commitment:()=>{if(s.commitment)return;s.commitment=s.day+37;record('公布 80 人到岗目标，截止第 '+s.commitment+' 日',{target:qty(80,'person'),deadline:day(s.commitment)});renderRoom();},
 crisis:()=>{s.crisis=s.crisis==='常态'?'加强协调':'常态';record('危机协调状态：'+s.crisis);renderRoom();},
 fund:b=>{if(s.committed)return;s.allocated=Math.max(0,Math.min(40e6,s.allocated+Number(b.dataset.delta)*5e6));s.approvals=[false,false];save();view===null?render():renderRoom();},
 'finance-approve':b=>{if(s.allocated!==40e6||s.committed)return;s.approvals[Number(b.dataset.id)]=true;record(['产业','Captain'][Number(b.dataset.id)]+'模拟席位确认北港项目');renderRoom();},
 'fund-commit':()=>{if(s.committed||s.allocated!==40e6||!s.approvals.every(Boolean))return;s.committed=true;s.projectDays=[Math.max(s.day+1,130),Math.max(s.day+7,136)];record('承诺北港项目 40M LNY，按两个里程碑支付',{commitment:money(40e6),milestones:s.projectDays.map(day)});view=null;render();toast('40M LNY 已冻结 · 到付款日结算');},
 issue:()=>{if(s.bond)return;const a=Math.min(s.bondOffer,20e6);s.bond={allocated:a,net:a*.98-200000,day:s.day+1,maturity:s.day+361};record('债券配售 '+compact(a)+' LNY，等待交割',{face:money(a),price:Season1.Price.from('0.98','LNY','face_unit').toCanonicalValue(),net:money(s.bond.net),settlement:day(s.bond.day)});renderRoom();toast('完成配售，国库将在交割日收到资金');},
 bank:b=>{s.bank=Number(b.dataset.id);s.amount=Math.min(s.amount,s.banks[s.bank].collateral*.8-s.banks[s.bank].loan,s.cash);save();view===null?render():renderRoom();},
 lend:()=>{const b=s.banks[s.bank];if(s.amount<=0||s.amount>b.collateral*.8-b.loan||s.amount>s.cash)return;s.cash-=s.amount;b.loan+=s.amount;s.loans.push({bank:s.bank,principal:s.amount,rate:s.rate+.5,due:s.day+7,repaid:false});record('向'+b.name+'发放 '+compact(s.amount)+' LNY 抵押贷款',{principal:money(s.amount),maturity:day(s.day+7),rate:Season1.ratio(s.rate+.5)});s.amount=Math.max(0,Math.min(s.amount,b.collateral*.8-b.loan,s.cash));view=null;render();toast('贷款到账 · 清算缺口已更新');},
 'announce-rate':()=>{s.rate=s.rateDraft??s.rate;record('公布政策利率 '+s.rate.toFixed(2)+'%',{rate:Season1.ratio(s.rate)});render();toast('政策利率已公布');},
 fx:()=>{if(s.fxAmount<=0||s.fxAmount>s.fx)return;s.fx-=s.fxAmount;s.cash+=s.fxAmount*7;record('卖出 '+compact(s.fxAmount)+' GCU，回收 '+compact(s.fxAmount*7)+' LNY',{sold:money(s.fxAmount,'GCU'),received:money(s.fxAmount*7),price:Season1.Price.from('7','LNY','GCU').toCanonicalValue()});render();toast('外汇与本币资产已同步结算');},
 expand:()=>{if(s.expansion||s.cash<20000)return;s.cash-=20000;s.expansion={end:s.day+5,done:false};record('钢厂扩建开工，支出 20,000 LNY',{cost:money(20000),ready:day(s.day+5)});render();toast('钢厂扩建开工 · 5 日后完工');},
 supplier:b=>{s.supplier=b.dataset.id;s.quantity=Math.min(s.quantity,s.supply[s.supplier]);save();view===null?render():renderRoom();},
 ship:()=>{const p=suppliers[s.supplier],q=quote();if(s.quantity<=0||s.quantity>s.supply[s.supplier]||q.total>s.cash)return;s.cash-=q.total;s.supply[s.supplier]-=s.quantity;s.shipments.push({id:s.shipments.length+1,name:p.name,quantity:s.quantity,start:s.day,arrival:s.day+p.days,cost:q.total,tariff:s.tariff,arrived:false});record('钢材 '+s.quantity+' tonne 装船，支出 '+fmt(q.total)+' GCU',{quantity:qty(s.quantity,'tonne'),cost:money(q.total,'GCU'),price:Season1.Price.from(String(p.price),'GCU','tonne').toCanonicalValue(),arrival:day(s.day+p.days)});s.quantity=Math.min(s.quantity,s.supply[s.supplier]);view=null;render();toast('货船已离港 · 库存将在到港后增加');},
 train:()=>{if((s.programme&&!s.programme.done)||s.seats<=0||s.seats>80||s.seats*2000>s.funds||s.seats>s.low)return;s.funds-=s.seats*2000;s.low-=s.seats;s.programme={n:s.seats,end:s.day+30,done:false,graduates:0};record('技术培训开班 '+s.seats+' 人',{people:qty(s.seats,'person'),cost:money(s.seats*2000),graduation:day(s.day+30)});view=null;render();toast('培训开始 · 毕业前不会增加技能人才');},
 match:()=>{const free=s.vacancies-s.placements.filter(x=>!x.done).reduce((a,b)=>a+b.n,0);if(s.match<=0||s.match>s.skilled||s.match>free)return;s.skilled-=s.match;s.placements.push({n:s.match,due:s.day+7,done:false});record('安排 '+s.match+' 人入职，第 '+(s.day+7)+' 日到岗',{people:qty(s.match,'person'),arrival:day(s.day+7)});s.match=Math.min(s.match,s.skilled);view=null;render();toast('岗位匹配完成 · 人员正在入职途中');},
 clinic:()=>{if(s.clinic<=0||s.clinic>s.backlog||s.clinic>60||s.clinic*100>s.healthFunds)return;let n=s.clinic;s.backlog-=n;s.visits+=n;s.healthFunds-=n*100;record('完成接诊 '+n+' 人，支出 '+n*100+' LNY',{people:qty(n,'person'),cost:money(n*100)});s.clinic=Math.min(s.clinic,s.backlog);render();toast('接诊完成 · 等候队列已缩短');}
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-cmd]');if(!b||b.disabled)return;const fn=commands[b.dataset.cmd];if(fn)try{const ret=fn(b);if(ret?.catch)ret.catch(err=>toast(err.message));}catch(err){console.error(err);toast('操作未完成：'+err.message);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')commands.close();});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='catalog-search'){catalogQuery=el.value;const start=el.selectionStart;renderCodex();$('#catalog-search').focus();$('#catalog-search').setSelectionRange(start,start);return;}if(el.dataset.field){const f=activeModule.fields.find(f=>f.key===el.dataset.field);if(f.type==='multi'){editValues[f.key]=[...document.querySelectorAll(`[data-field="${f.key}"]:checked`)].map(e=>e.dataset.multi);}else editValues[f.key]=f.type==='number'?(el.value===''?null:Number(el.value)):el.value;if(f.type==='number')$$(`[data-field="${f.key}"]`).forEach(other=>{if(other!==el)other.value=el.value;});}if(el.dataset.rowKey){editValues[el.dataset.id][Number(el.dataset.index)][el.dataset.rowKey]=['amount','day'].includes(el.dataset.rowKey)?Number(el.value):el.value;}if(el.dataset.control){s[el.dataset.control]=clampControl(el.dataset.control,Number(el.value));$$(`[data-control="${el.dataset.control}"]`).forEach(x=>{if(x!==el)x.value=s[el.dataset.control];});save();}});
document.addEventListener('change',e=>{if(e.target.dataset.unitField){editValues[e.target.dataset.unitField+'__unit']=e.target.value;renderEditor();}if(e.target.dataset.control){const target=e.target;queueMicrotask(()=>{if(target.isConnected){view===null?render():renderRoom();}});}if(e.target.dataset.field&&e.target.tagName==='SELECT'){editValues[e.target.dataset.field]=e.target.value;const el=e.target;if(activeModule.fields.some(f=>f.unit?.includes('商品单位')||f.currencyFrom))renderEditor();}if(e.target.dataset.rowKey){const el=e.target;editValues[el.dataset.id][Number(el.dataset.index)][el.dataset.rowKey]=['amount','day'].includes(el.dataset.rowKey)?Number(el.value):el.value;}});
document.addEventListener('dragstart',e=>{if(e.target.dataset.token){e.dataTransfer.setData('text/plain',e.target.dataset.token);e.dataTransfer.effectAllowed='move';}});
document.addEventListener('dragover',e=>{const zone=e.target.closest('[data-drop]');if(zone){e.preventDefault();zone.classList.add('over');}});
document.addEventListener('dragleave',e=>{e.target.closest('[data-drop]')?.classList.remove('over');});
document.addEventListener('drop',e=>{const zone=e.target.closest('[data-drop]');if(!zone)return;e.preventDefault();zone.classList.remove('over');const token=e.dataTransfer.getData('text/plain');if(zone.dataset.drop===token&&role==='finance')commands.fund({dataset:{delta:token==='fund'?'1':'-1'}});});
Promise.all([fetch('catalog.json').then(r=>r.json()),window.Season1?Promise.resolve():new Promise(resolve=>document.addEventListener('season1-ready',resolve,{once:true}))]).then(([c])=>{catalog=c;setRole(role);if(params.get('module'))openModule(params.get('module'));window.GameTest={state:()=>structuredClone(s),role:()=>role,catalog:()=>catalog,policies:()=>structuredClone(data.policies),setRole,openModule,openRoom:showRoom,advance};}).catch(err=>{$('#game').innerHTML='<p style="padding:40px;background:#fff">加载未完成：'+esc(err.message)+'</p>';});
function scenePlay(){let content='';switch(role){case'finance':content=`<small>国库资金 · 每枚 5M LNY</small><div class="tokens">${Array.from({length:8-s.allocated/5e6},()=>`<button class="token" draggable="${!s.committed}" data-token="fund" data-cmd="fund" data-delta="1" aria-label="直接拨入 5M LNY" ${s.committed?'disabled':''}>5M</button>`).join('')}</div><p>${s.committed?'建设资金已承诺':s.allocated===40e6?'资金已就位，等待项目确认':'点击筹码或拖入建设工地'}</p><div class="scene-action">${button(s.committed?'查看施工进度':'确认资金配置','room',`data-id="${s.committed?2:0}"`,'mini')}<b>${compact(s.allocated)} / 40M</b></div>`;break;case'captain':content=`<small>人才方案 · 三选一</small><div class="scene-choices">${Object.entries(plans).map(([id,p])=>`<button class="${s.plan===id?'chosen':''}" data-cmd="plan" data-id="${id}" ${s.active?'disabled':''}><span>${p.icon}</span>${p.title}<em>${p.days+7} 日 · ${p.capital} 点</em></button>`).join('')}</div><p>${s.active?'计划执行中 · 第 '+s.active.arrivalDay+' 日到岗':'方案变更后，内阁须重新确认'}</p>${button('分配议程支持','room','data-id="0"','mini')}`;break;case'central_bank':content=`<small>清算网络 · 选择银行</small><div class="scene-choices">${s.banks.map((b,i)=>`<button class="${s.bank===i?'chosen':''}" data-cmd="bank" data-id="${i}"><span>▥</span>${b.name}<em>缺口 ${compact(Math.max(0,b.gap-b.loan))} LNY</em></button>`).join('')}</div>${slider('本次贷款','amount',s.amount,0,Math.min(s.cash,s.banks[s.bank].collateral*.8-s.banks[s.bank].loan),200000,'LNY')}${button('沿网络放款','lend',s.amount<=0?'disabled':'','mini')}`;break;case'industry':const p=production();content=`<small>工业供电 · 200 MWh/日</small><div class="energy-split"><span>⚒ 钢厂 <b>${s.powerSteel}</b></span><span>⚙ 机械厂 <b>${200-s.powerSteel}</b></span></div>${slider('钢厂分配','powerSteel',s.powerSteel,0,200,10,'MWh/日')}<div class="scene-action"><span>下日生产</span><b>${p.steel} 吨钢 · ${p.machines} 台机械</b></div><p>电力划分后，右下角推进生产。</p>`;break;case'trade':content=`<small>采购钢材 · 选择航线</small><div class="scene-choices">${Object.entries(suppliers).map(([id,p])=>`<button class="${s.supplier===id?'chosen':''}" data-cmd="supplier" data-id="${id}"><span>${id==='near'?'⚓':'⛵'}</span>${p.name}<em>${p.days} 日 · ${p.price} GCU/tonne</em></button>`).join('')}</div>${slider('采购数量','quantity',s.quantity,0,s.supply[s.supplier],5,'tonne')}${button('查看含税报价','room','data-id="1"','mini')}`;break;case'social':content=`<small>技术学院 · 80 个教学名额</small>${people(s.programme&&!s.programme.done?s.programme.n:s.seats,'learning')}${slider('招生人数','seats',s.seats,0,80,5,'人')}<div class="scene-action">${button(s.programme&&!s.programme.done?'正在培训':'支付并开班','train',s.seats<=0||s.seats*2000>s.funds||(s.programme&&!s.programme.done)?'disabled':'','mini')}<b>${fmt(s.seats*2000)} LNY</b></div>`;break;}return `<div class="scene-play ${role}">${content}</div>`;}
